def _encode(rows, format_name):
    if format_name == 'framed':
        output = bytearray()
        for identity, payload in rows:
            name = identity.encode('ascii')
            output += len(name).to_bytes(1, 'big') + name
            output += len(payload).to_bytes(2, 'big') + payload
        return bytes(output)
    return b''.join(
        json.dumps(
